import React, { useRef, useEffect } from 'react';
import { View, StyleSheet, TouchableOpacity, Text, Animated, Dimensions } from 'react-native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { useNavigation, useRoute } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';

import TelaInicio from '../screens/Inicio';
import TelaCriarEscala from '../screens/TelaCriarEscala';
import TelaListaEscalas from '../screens/TelaListaEscalas';
import TelaDetalhesEscala from '../screens/DetalhesEscala';
import RepertoiresScreen from '../screens/Repertorios';
import AdicionarRepertorio from '../screens/AdicionarRepertorio';
import DetalheRepertorio from '../screens/DetalheRepertorio';
import VisualizarArquivo from '../screens/VisualizarArquivo';
import PresencaScreen from '../screens/Presenca';
import AvisosScreen from '../screens/Avisos';
import EnsaiosScreen from '../screens/Ensaios';
import TelaAniversariantes from '../screens/Aniversariantes';
import TelaAgenda from '../screens/Agenda';

const { width: LARGURA_TELA } = Dimensions.get('window');
const Stack = createNativeStackNavigator();

const ITEMS_BARRA = [
  { id: 'avisos', rotulo: 'Avisos', rota: 'Avisos', icone: 'bell-alert-outline', gradiente: ['#F59E0B', '#EF4444'] },
  { id: 'repertorios', rotulo: 'Repertório', rota: 'Repertorios', icone: 'music-circle-outline', gradiente: ['#EC4899', '#8B5CF6'] },
  { id: 'escalas', rotulo: 'Escalas', rota: 'Escalas', icone: 'calendar-check-outline', gradiente: ['#10B981', '#059669'] },
  { id: 'inicio', rotulo: 'Início', rota: 'Inicio', icone: 'home', gradiente: ['#FF9A3C', '#FF6B00'], principal: true },
  { id: 'presenca', rotulo: 'Presença', rota: 'Presenca', icone: 'account-check-outline', gradiente: ['#3B82F6', '#1D4ED8'] },
  { id: 'ensaios', rotulo: 'Ensaios', rota: 'Ensaios', icone: 'account-group-outline', gradiente: ['#F97316', '#EA580C'] },
  { id: 'aniversariantes', rotulo: 'Aniversários', rota: 'Aniversariantes', icone: 'gift-outline', gradiente: ['#EC4899', '#DB2777'] },
  { id: 'agenda', rotulo: 'Agenda', rota: 'Agenda', icone: 'calendar-month-outline', gradiente: ['#14B8A6', '#0D9488'] },
];

const COR_FUNDO_BARRA = '#1C1C1E';
const COR_TEXTO_INATIVO = '#8E8E93';

const BarraNavegacaoFixa = () => {
  const navegacao = useNavigation();
  const rotaAtual = useRoute().name;

  const animOpacidade = useRef(new Animated.Value(0)).current;
  const animEscala = useRef(ITEMS_BARRA.map(() => new Animated.Value(1))).current;

  useEffect(() => {
    Animated.timing(animOpacidade, { toValue: 1, duration: 400, useNativeDriver: true }).start();
  }, []);

  useEffect(() => {
    ITEMS_BARRA.forEach((item, idx) => {
      Animated.spring(animEscala[idx], {
        toValue: item.rota === rotaAtual ? 1.15 : 1,
        speed: 50,
        bounciness: 1,
        useNativeDriver: true,
      }).start();
    });
  }, [rotaAtual]);

  if (['SplashLogo', 'Login', 'Cadastro'].includes(rotaAtual)) return null;

  return (
    <Animated.View style={[estilos.barraContainer, { opacity: animOpacidade }]}>
      <View style={estilos.barraFundo}>
        <View style={estilos.recorteCentral}>
          <TouchableOpacity activeOpacity={0.8} onPress={() => navegacao.navigate('Inicio')}>
            <LinearGradient colors={ITEMS_BARRA[3].gradiente} style={estilos.botaoCentral}>
              <MaterialCommunityIcons name={ITEMS_BARRA[3].icone} size={26} color="#FFF" />
            </LinearGradient>
          </TouchableOpacity>
        </View>

        {ITEMS_BARRA.map((item, idx) => {
          if (item.principal) return null;
          const selecionado = item.rota === rotaAtual;
          return (
            <TouchableOpacity
              key={item.id}
              style={estilos.item}
              activeOpacity={0.7}
              onPress={() => navegacao.navigate(item.rota as never)}
            >
              <Animated.View style={{ transform: [{ scale: animEscala[idx] }] }}>
                <LinearGradient
                  colors={selecionado ? item.gradiente : ['transparent', 'transparent']}
                  style={[estilos.iconeBase, selecionado && estilos.iconeAtivo]}
                >
                  <MaterialCommunityIcons
                    name={item.icone}
                    size={19}
                    color={selecionado ? '#FFF' : COR_TEXTO_INATIVO}
                  />
                </LinearGradient>
              </Animated.View>
              <Text style={[estilos.rotulo, { color: selecionado ? item.gradiente[0] : COR_TEXTO_INATIVO }]}>
                {item.rotulo}
              </Text>
            </TouchableOpacity>
          );
        })}
      </View>
    </Animated.View>
  );
};

export default function AppNavigator() {
  return (
    <View style={estilos.containerPrincipal}>
      <View style={estilos.areaConteudo}>
        <Stack.Navigator initialRouteName="Inicio" screenOptions={{ headerShown: false }}>
          <Stack.Screen name="Inicio" component={TelaInicio} />
          <Stack.Screen name="CriarEscala" component={TelaCriarEscala} />
          <Stack.Screen name="Escalas" component={TelaListaEscalas} />
          <Stack.Screen name="DetalhesEscala" component={TelaDetalhesEscala} />
          <Stack.Screen name="Repertorios" component={RepertoiresScreen} />
          <Stack.Screen name="AdicionarRepertorio" component={AdicionarRepertorio} />
          <Stack.Screen name="DetalheRepertorio" component={DetalheRepertorio} />
          <Stack.Screen name="VisualizarArquivo" component={VisualizarArquivo} />
          <Stack.Screen name="Presenca" component={PresencaScreen} />
          <Stack.Screen name="Avisos" component={AvisosScreen} />
          <Stack.Screen name="Ensaios" component={EnsaiosScreen} />
          <Stack.Screen name="Aniversariantes" component={TelaAniversariantes} />
          <Stack.Screen name="Agenda" component={TelaAgenda} />
        </Stack.Navigator>
      </View>
      <BarraNavegacaoFixa />
    </View>
  );
}

const estilos = StyleSheet.create({
  containerPrincipal: { flex: 1, backgroundColor: '#17152B' },
  areaConteudo: { flex: 1, paddingBottom: 105 },
  barraContainer: { position: 'absolute', bottom: 0, left: 0, right: 0, alignItems: 'center', zIndex: 9999 },
  barraFundo: {
    width: LARGURA_TELA - 12, height: 88, backgroundColor: COR_FUNDO_BARRA,
    borderTopLeftRadius: 26, borderTopRightRadius: 26, borderBottomLeftRadius: 14, borderBottomRightRadius: 14,
    flexDirection: 'row', justifyContent: 'space-around', alignItems: 'flex-end',
    paddingHorizontal: 6, paddingBottom: 10,
    shadowColor: '#000', shadowOffset: { width: 0, height: -4 }, shadowOpacity: 0.4, shadowRadius: 14, elevation: 25,
    position: 'relative',
  },
  recorteCentral: {
    position: 'absolute', top: -24, left: '50%', transform: [{ translateX: -28 }],
    width: 56, height: 56, borderRadius: 28, backgroundColor: COR_FUNDO_BARRA,
    alignItems: 'center', justifyContent: 'center',
    shadowColor: '#FF9A3C', shadowOffset: { width: 0, height: 3 }, shadowOpacity: 0.5, shadowRadius: 10,
  },
  botaoCentral: { width: 48, height: 48, borderRadius: 24, alignItems: 'center', justifyContent: 'center' },
  item: { alignItems: 'center', justifyContent: 'center', flex: 1, maxWidth: 52 },
  iconeBase: { width: 32, height: 32, borderRadius: 16, alignItems: 'center', justifyContent: 'center', marginBottom: 2 },
  iconeAtivo: { shadowColor: '#000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.3, shadowRadius: 4 },
  rotulo: { fontSize: 9, fontWeight: '500', textAlign: 'center' },
});